    @Test
    public void testThreadSafe(){
        String abc = "2021-08-11 11:00:00";
        for(int i = 0;i<20;i++){

            new Thread(()->{
                    try {
                        System.out.println(yyyyMMddHMS.format(yyyyMMddHMS.parse(abc)));
                    } catch (ParseException e) {
                        e.printStackTrace();
                    }
            }).start();
        }
    }

